(r, big) => {
    const n = big ? 1000 : r.int(1, 9), hi = big ? 1000000000 : 20;
    const L = [-1], R = [-1], V = [r.int(1, hi)], open = [0];
    for (let i = 1; i < n; i++) {
      const k = r.int(0, open.length - 1), p = open[k];
      if (L[p] < 0) L[p] = i;
      else { R[p] = i; open[k] = open[open.length - 1]; open.pop(); }
      L.push(-1); R.push(-1); V.push(r.int(1, hi)); open.push(i);
    }
    let s = "";
    const st = [[0, 0]];
    while (st.length) {
      const [x, d] = st.pop();
      s += "-".repeat(d) + V[x];
      if (R[x] >= 0) st.push([R[x], d + 1]);
      if (L[x] >= 0) st.push([L[x], d + 1]);
    }
    return [s];
  }

