function rebuildFromOutline(outline: string): TreeNode | null {
  const tokens: [number, number][] = [];
  for (let i = 0; i < outline.length;) {
    let d = 0, v = 0;
    while (outline[i] === "-") { d++; i++; }
    while (i < outline.length && outline[i] !== "-") v = v * 10 + Number(outline[i++]);
    tokens.push([d, v]);
  }
  let pos = 0;
  const build = (d: number): TreeNode | null => {
    if (pos === tokens.length || tokens[pos][0] !== d) return null;
    const node = new TreeNode(tokens[pos++][1]);
    node.left = build(d + 1);
    node.right = build(d + 1);
    return node;
  };
  return build(0);
}

