    def rebuildFromOutline(self, outline: str) -> Optional[TreeNode]:
        tokens = []
        i = 0
        while i < len(outline):
            d = 0
            while outline[i] == "-":
                d += 1
                i += 1
            j = i
            while j < len(outline) and outline[j] != "-":
                j += 1
            tokens.append((d, int(outline[i:j])))
            i = j
        pos = 0

        def build(d: int) -> Optional[TreeNode]:
            nonlocal pos
            if pos == len(tokens) or tokens[pos][0] != d:
                return None
            node = TreeNode(tokens[pos][1])
            pos += 1
            node.left = build(d + 1)
            node.right = build(d + 1)
            return node

        return build(0)

