function rebuildFromOutline(outline: string): TreeNode | null {
  const path: TreeNode[] = [];
  let i = 0;
  while (i < outline.length) {
    let depth = 0, value = 0;
    while (outline[i] === "-") { depth++; i++; }
    while (i < outline.length && outline[i] !== "-") value = value * 10 + Number(outline[i++]);
    const node = new TreeNode(value);
    while (path.length > depth) path.pop();
    if (path.length) {
      const parent = path[path.length - 1];
      if (!parent.left) parent.left = node;
      else parent.right = node;
    }
    path.push(node);
  }
  return path.length ? path[0] : null;
}

